import json
pts=[(0,-2),(2,0),(5,3),(6,0),(8,-4)]
def r(t):
    for (a,b),(c,d) in zip(pts,pts[1:]):
        if a<=t<=c: return b+(d-b)*(t-a)/(c-a)
def G(x,n=8000):
    # integral from 2 to x via trapezoid (exact for piecewise linear w/ fine grid)
    h=(x-2)/n
    s=sum((r(2+i*h)+r(2+(i+1)*h))/2*h for i in range(n)) if n and x!=2 else 0
    return 12+s
vals={x:G(x) for x in [0,2,6,8]}
best=max(vals,key=vals.get)
opts=[0,2,6,8]
print(json.dumps({"computed_key_index":opts.index(best),"conceptual_only":False,"details":str(vals)}))

